test_setup_files.tests/processor_test.rs:
use idempotency::Processor;

#[test]
fn duplicate_key_within_window_not_reexecuted() {
    let mut p = Processor::new(10);
    let first = p.process("order-1", 5, 0);
    let second = p.process("order-1", 999, 5);
    assert_eq!(second, first);
    assert_eq!(p.effects.len(), 1);
}

#[test]
fn different_keys_both_execute() {
    let mut p = Processor::new(10);
    p.process("a", 1, 0);
    p.process("b", 2, 0);
    assert_eq!(p.effects.len(), 2);
}

#[test]
fn reexecutes_after_window_expires() {
    let mut p = Processor::new(10);
    p.process("order-1", 5, 0);
    p.process("order-1", 5, 9);
    assert_eq!(p.effects.len(), 1);
    p.process("order-1", 7, 10);
    assert_eq!(p.effects.len(), 2);
    assert_eq!(p.effects[1].1, 7);
}

