use std::collections::HashMap;

#[derive(Debug, Clone, PartialEq)]
pub struct ProcResult {
    pub key: String,
    pub payload: i32,
    pub processed_at: i64,
}

pub struct Processor {
    pub window: i64,
    pub effects: Vec<(String, i32)>,
    seen: HashMap<String, (ProcResult, i64)>,
}

impl Processor {
    pub fn new(window: i64) -> Self {
        Processor { window, effects: Vec::new(), seen: HashMap::new() }
    }

    pub fn process(&mut self, key: &str, payload: i32, now: i64) -> ProcResult {
        if let Some((result, recorded_at)) = self.seen.get(key) {
            if now - recorded_at < self.window {
                return result.clone();
            }
        }
        self.effects.push((key.to_string(), payload));
        let result = ProcResult { key: key.to_string(), payload, processed_at: now };
        self.seen.insert(key.to_string(), (result.clone(), now));
        result
    }
}

